{
  "units": [
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "The purpose of 8 FAM 801.2 is to provide guidance concerning the use of information request letters (IRLs) and information notices (INs)."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "Information request letters (IRLs) are defined as personalized, standardized letters containing a date and signature block that request additional information, documentation, or action needed from the applicant to process a passport application."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Before suspending an application, the adjudicator must fully adjudicate the application to ensure that all issues are addressed."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "IRLs are carefully crafted to clearly and accurately communicate statutory, regulatory, and other Department requirements."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F003"],
      "kind": "prohibition",
      "meaning": "Passport agencies and centers are prohibited from making unilateral changes or alterations to IRLs without approval from the Office of Adjudication (CA/PPT/S/A), except in extenuating circumstances on a case-by-case basis with the approval of passport agency or center management (such as when requesting a birth certificate instead of a notification of birth registration and the applicant insists that the notification is the birth certificate)."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F003"],
      "kind": "requirement",
      "meaning": "Posts must use the cleared language in IRLs."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F003"],
      "kind": "permission",
      "meaning": "Posts are authorized to modify the cleared language of IRLs to suit local logistical requirements and other local concerns, such as available documentation."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "IRLs do not constitute adjudicative guidance."
    },
    {
      "quote_ref": "F006",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A passport application must be adjudicated in accordance with 8 FAM before selecting the appropriate IRL to address any deficiencies related to the passport or Consular Report of Birth Abroad (CRBA)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "Information notices (INs) are standardized notices that provide passport bearers with information concerning their passports."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "An IN may be included to explain why a passport was limited in validity, what documentation is needed to obtain a fully valid passport, or both."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "INs are carefully crafted to communicate passport information clearly and accurately."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Passport agencies and centers are prohibited from making unilateral changes or alterations to INs without CA/PPT/S/A approval, except in extenuating circumstances on a case-by-case basis with the approval of passport agency or center management (such as when using endorsement 46 to limit a passport for a special problem)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": [],
      "kind": "exemption",
      "meaning": "INs do not require an applicant response and do not need to be personalized with the applicant's name and address."
    },
    {
      "quote_ref": "F008",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "When tailoring correspondence to a specific situation, posts may consult Passport Services' IRL index and IN index, or contact AskPPTAdjudication@state.gov."
    }
  ]
}
